public static Sentinel.DashboardResponse.Builder mergeDashboardResponse(Sentinel.DashboardResponse dst, Sentinel.DashboardResponse src) {
Sentinel.DashboardResponse.Builder builder = dst.toBuilder();
if (!dst.hasClusterInfo() && src.hasClusterInfo()) { builder.setClusterInfo(src.getClusterInfo()); }
if (!dst.hasClusterHealth() && src.hasClusterHealth()) { builder.setClusterHealth(src.getClusterHealth()); }
if (dst.getNodeMetricsList().isEmpty()) { builder.addAllNodeMetrics(src.getNodeMetricsList()); }
if (dst.getGrpcStatsList().isEmpty()) { builder.addAllGrpcStats(src.getGrpcStatsList()); }
if (dst.getPersistenceStatusList().isEmpty()) { builder.addAllPersistenceStatus(src.getPersistenceStatusList()); }
if (dst.getNetworkStatsList().isEmpty()) { builder.addAllNetworkStats(src.getNetworkStatsList()); }
if (dst.getThreadInfoList().isEmpty()) { builder.addAllThreadInfo(src.getThreadInfoList()); }
if (dst.getTokenCacheStatsList().isEmpty()) { builder.addAllTokenCacheStats(src.getTokenCacheStatsList()); }
if (dst.getMapStatsList().isEmpty()) { builder.addAllMapStats(src.getMapStatsList()); }
return builder;
}
